fn sort_by(comptime T26: type, xs: *CxList(T26), cmp: CxFn2(T26, T26, i64)) *CxList(T26) {
    return b0: { const len_: i64 = cx_list_len(xs); break :b0 (if ((len_ <= 1)) xs else qsort_by(T26, xs, cmp, 0, (len_ -% 1))); };
}

fn qsort_by(comptime T27: type, xs: *CxList(T27), cmp: CxFn2(T27, T27, i64), lo: i64, hi: i64) *CxList(T27) {
    var _tl_xs = xs;
    var _tl_lo = lo;
    while (true) {
        if ((_tl_lo >= hi)) { return _tl_xs; } else { const xs2 = sort_med3(T27, _tl_xs, cmp, _tl_lo, (_tl_lo +% @divTrunc((hi -% _tl_lo), 2)), hi); const pr = sort_partition(T27, xs2, cmp, _tl_lo, hi, _tl_lo, cx_list_at(xs2, hi)); const xs3 = qsort_by(T27, pr.list, cmp, _tl_lo, (pr.pivot -% 1)); { const _tj4_0 = xs3; const _tj4_2 = (pr.pivot +% 1); _tl_xs = _tj4_0; _tl_lo = _tj4_2; continue; } }
    }
}

fn sort_med3(comptime T28: type, xs: *CxList(T28), cmp: CxFn2(T28, T28, i64), a_: i64, b_: i64, c_: i64) *CxList(T28) {
    return b0: { const va = cx_list_at(xs, a_); break :b0 b1: { const vb = cx_list_at(xs, b_); break :b1 b2: { const vc = cx_list_at(xs, c_); break :b2 (if ((cmp.call(cmp.ctx, va, vb) <= 0)) (if ((cmp.call(cmp.ctx, vb, vc) <= 0)) sort_swap(T28, xs, b_, c_) else (if ((cmp.call(cmp.ctx, va, vc) <= 0)) xs else sort_swap(T28, xs, a_, c_))) else (if ((cmp.call(cmp.ctx, va, vc) <= 0)) sort_swap(T28, xs, a_, c_) else (if ((cmp.call(cmp.ctx, vb, vc) <= 0)) xs else sort_swap(T28, xs, b_, c_)))); }; }; };
}

fn sort_swap(comptime T29: type, xs: *CxList(T29), i_: i64, j: i64) *CxList(T29) {
    return (if ((i_ == j)) xs else b1: { const vi = cx_list_at(xs, i_); break :b1 cx_list_set_at(cx_list_set_at(xs, i_, cx_list_at(xs, j)), j, vi); });
}

fn sort_partition(comptime T30: type, xs: *CxList(T30), cmp: CxFn2(T30, T30, i64), j: i64, hi: i64, i_: i64, pv: T30) SortPartition(T30) {
    var _tl_xs = xs;
    var _tl_j = j;
    var _tl_i = i_;
    while (true) {
        if ((_tl_j >= hi)) { const xs2 = sort_swap(T30, _tl_xs, _tl_i, hi); return cx_new(SortPartitionS(T30){ .list = xs2, .pivot = _tl_i }); } else { if ((cmp.call(cmp.ctx, cx_list_at(_tl_xs, _tl_j), pv) < 0)) { { const _tj2_0 = sort_swap(T30, _tl_xs, _tl_i, _tl_j); const _tj2_2 = (_tl_j +% 1); const _tj2_4 = (_tl_i +% 1); _tl_xs = _tj2_0; _tl_j = _tj2_2; _tl_i = _tj2_4; continue; } } else { { const _tj2_0 = _tl_xs; const _tj2_2 = (_tl_j +% 1); const _tj2_4 = _tl_i; _tl_xs = _tj2_0; _tl_j = _tj2_2; _tl_i = _tj2_4; continue; } } }
    }
}

fn int_widen(n_: i64) i64 {
    return n_;
}

fn helper(x: i64) i64 {
    return (x +% 1);
}

fn mask32() i64 {
    return 4294967295;
}

fn ch(x: i64, y: i64, z_: i64) i64 {
    return ((x & y) ^ ((x ^ mask32()) & z_));
}

fn map_list(comptime T38: type, comptime T39: type, f: CxFn1(T38, T39), xs: *CxList(T38)) *CxList(T39) {
    return map_list_loop(T38, T39, f, xs, 0, cx_list_len(xs), cx_ll_empty(T39));
}

fn map_list_loop(comptime T40: type, comptime T41: type, f: CxFn1(T40, T41), xs: *CxList(T40), i_: i64, len_: i64, acc_: *CxList(T41)) *CxList(T41) {
    var _tl_i = i_;
    var _tl_acc = acc_;
    while (true) {
        if ((_tl_i == len_)) { return _tl_acc; } else { { const _tj1_2 = (_tl_i +% 1); const _tj1_4 = cx_ll_push(_tl_acc, f.call(f.ctx, cx_list_at(xs, _tl_i))); _tl_i = _tj1_2; _tl_acc = _tj1_4; continue; } }
    }
}

fn is_digit(c_: i64) bool {
    return (if (((c_) >= 3)) ((c_) <= 12) else false);
}

fn is_upper(c_: i64) bool {
    return (if (((c_) >= 39)) ((c_) <= 64) else false);
}

fn is_letter(c_: i64) bool {
    return (if (((c_) >= 97)) ((c_) <= 127) else (if (((c_) >= 13)) ((c_) <= 64) else false));
}

fn iv_i64_max() i64 {
    return 9223372036854775807;
}

fn iv_i64_min() i64 {
    return ((0 -% 9223372036854775807) -% 1);
}

fn iv_unknown() Interval {
    return cx_new(IntervalS{ .lo = iv_i64_min(), .hi = iv_i64_max() });
}

fn iv_empty() Interval {
    return cx_new(IntervalS{ .lo = 1, .hi = 0 });
}

fn iv_is_empty(a_: Interval) bool {
    return (a_.lo > a_.hi);
}

fn iv_add_overflows(a_: i64, b_: i64) bool {
    return (if ((b_ > 0)) (a_ > (iv_i64_max() -% b_)) else (a_ < (iv_i64_min() -% b_)));
}

fn iv_sub_overflows(a_: i64, b_: i64) bool {
    return (if ((b_ > 0)) (a_ < (iv_i64_min() +% b_)) else (a_ > (iv_i64_max() +% b_)));
}

fn iv_mul_overflows(a_: i64, b_: i64) bool {
    return (if (((a_ == 0) or (b_ == 0))) false else (if ((a_ == (0 -% 1))) (b_ == iv_i64_min()) else (if ((b_ == (0 -% 1))) (a_ == iv_i64_min()) else (if ((b_ > 0)) ((a_ > @divTrunc(iv_i64_max(), b_)) or (a_ < @divTrunc(iv_i64_min(), b_))) else ((a_ > @divTrunc(iv_i64_min(), b_)) or (a_ < @divTrunc(iv_i64_max(), b_)))))));
}

fn iv_int_min(a_: i64, b_: i64) i64 {
    return (if ((a_ <= b_)) a_ else b_);
}

fn iv_int_max(a_: i64, b_: i64) i64 {
    return (if ((a_ >= b_)) a_ else b_);
}

fn iv_mul(a_: Interval, b_: Interval) Interval {
    return (if ((iv_is_empty(a_) or iv_is_empty(b_))) iv_empty() else (if ((((iv_mul_overflows(a_.lo, b_.lo) or iv_mul_overflows(a_.lo, b_.hi)) or iv_mul_overflows(a_.hi, b_.lo)) or iv_mul_overflows(a_.hi, b_.hi))) iv_unknown() else b2: { const p1: i64 = (a_.lo *% b_.lo); break :b2 b3: { const p2: i64 = (a_.lo *% b_.hi); break :b3 b4: { const p3: i64 = (a_.hi *% b_.lo); break :b4 b5: { const p4: i64 = (a_.hi *% b_.hi); break :b5 cx_new(IntervalS{ .lo = iv_int_min(iv_int_min(p1, p2), iv_int_min(p3, p4)), .hi = iv_int_max(iv_int_max(p1, p2), iv_int_max(p3, p4)) }); }; }; }; }));
}

fn iv_div(a_: Interval, b_: Interval) Interval {
