{ .MkTup2 => |_p3| b3: { const ctx3 = _p3[0]; const el_expr = _p3[1]; break :b3 Tup2(LiftCtx, IRExpr){ .MkTup2 = .{ ctx3, b5: { _ = cx_deck_enter(); const _dr5 = cx_new(IRExprS{ .IrIf = .{ c_expr, th_expr, el_expr, t, s_ } }); _ = cx_deck_exit(); break :b5 _dr5; } } }; },  }; },  }; },  }; }, .IrLet => |_p0| b0: { const n_ = _p0[0]; const t = _p0[1]; const v_ = _p0[2]; const b_ = _p0[3]; const s_ = _p0[4]; break :b0 switch (lift_expr(ctx_, enclosing, v_)) { .MkTup2 => |_p1| b1: { const ctx1 = _p1[0]; const v_expr = _p1[1]; break :b1 b2: { const b_enclosing = skip_list_text_insert(enclosing, n_); break :b2 switch (lift_expr(ctx1, b_enclosing, b_)) { .MkTup2 => |_p3| b3: { const ctx2 = _p3[0]; const b_expr = _p3[1]; break :b3 Tup2(LiftCtx, IRExpr){ .MkTup2 = .{ ctx2, b5: { _ = cx_deck_enter(); const _dr5 = cx_new(IRExprS{ .IrLet = .{ n_, t, v_expr, b_expr, s_ } }); _ = cx_deck_exit(); break :b5 _dr5; } } }; },  }; }; },  }; }, .IrApply => |_p0| b0: { const f = _p0[0]; const a_ = _p0[1]; const t = _p0[2]; const s_ = _p0[3]; break :b0 switch (lift_expr(ctx_, enclosing, f)) { .MkTup2 => |_p1| b1: { const ctx1 = _p1[0]; const f_expr = _p1[1]; break :b1 switch (lift_expr(ctx1, enclosing, a_)) { .MkTup2 => |_p2| b2: { const ctx2 = _p2[0]; const a_expr = _p2[1]; break :b2 Tup2(LiftCtx, IRExpr){ .MkTup2 = .{ ctx2, b4: { _ = cx_deck_enter(); const _dr4 = cx_new(IRExprS{ .IrApply = .{ f_expr, a_expr, t, s_ } }); _ = cx_deck_exit(); break :b4 _dr4; } } }; },  }; },  }; }, .IrList => |_p0| b0: { const es = _p0[0]; const t = _p0[1]; const s_ = _p0[2]; break :b0 switch (lift_exprs(ctx_, enclosing, es, 0, cx_list_len(es), cx_ll_empty(IRExpr))) { .MkTup2 => |_p1| b1: { const ctx1 = _p1[0]; const es_lifted = _p1[1]; break :b1 Tup2(LiftCtx, IRExpr){ .MkTup2 = .{ ctx1, b3: { _ = cx_deck_enter(); const _dr3 = cx_new(IRExprS{ .IrList = .{ es_lifted, t, s_ } }); _ = cx_deck_exit(); break :b3 _dr3; } } }; },  }; }, .IrMatch => |_p0| b0: { const sc = _p0[0]; const bs = _p0[1]; const t = _p0[