        out.append(al, @intCast(128 + (v & 63))) catch @panic("oom");
    } else if (c < 67712) {
        const v = c - 2176;
        out.append(al, @intCast(224 + (v >> 12))) catch @panic("oom");
        out.append(al, @intCast(128 + ((v >> 6) & 63))) catch @panic("oom");
        out.append(al, @intCast(128 + (v & 63))) catch @panic("oom");
